#include "mobile_robot_hardware/protocol.hpp"
namespace mobile_robot_hardware::protocol { uint16_t crc16_ccitt_false(const uint8_t* data,const std::size_t size){uint16_t crc=0xFFFFU;for(std::size_t i=0;i<size;++i){crc^=static_cast<uint16_t>(data[i])<<8U;for(uint8_t bit=0;bit<8U;++bit){crc=(crc&0x8000U)!=0U?static_cast<uint16_t>((crc<<1U)^0x1021U):static_cast<uint16_t>(crc<<1U);}}return crc;} std::optional<Packet> decode_frame(const std::vector<uint8_t>& frame){if(frame.size()<sizeof(Header)+sizeof(uint16_t))return std::nullopt;Packet packet{};std::memcpy(&packet.header,frame.data(),sizeof(Header));if(packet.header.magic!=kMagic||packet.header.version!=kVersion||packet.header.payload_size>kMaximumPayloadSize)return std::nullopt;const std::size_t expected=sizeof(Header)+packet.header.payload_size+sizeof(uint16_t);if(frame.size()!=expected)return std::nullopt;std::memcpy(packet.payload.data(),frame.data()+sizeof(Header),packet.header.payload_size);std::memcpy(&packet.crc,frame.data()+sizeof(Header)+packet.header.payload_size,sizeof(packet.crc));const uint16_t calculated=crc16_ccitt_false(frame.data(),sizeof(Header)+packet.header.payload_size);if(calculated!=packet.crc)return std::nullopt;return packet;} }
